import IFrame from './IFrame';
import { options } from '../Options';

/**
 * Uses the following icons:
 *   https://iconmonstr.com/magnifier-7-svg/
 *   https://iconmonstr.com/magnifier-8-svg/
 */
export class Image extends IFrame {
  private imageBuffer: string = '';
  private imageMimeType: string = 'image/png';
  private zoomLevel: number = 1;

  public activate(mimeType: string) {
    this.zoomLevel = options.get<number>('zoomLevel', 1);

    super.activate('text/html');

    this.imageMimeType = mimeType;
  }

  // TODO: this whole renderer should be a separate package with the contents parsed into a minified file
  private css(): string {
    return `
html, body {
  margin: 0;
  padding: 0;
}

body > img {
  --z: ${this.zoomLevel};
  image-rendering: pixelated;
  transform: scale(var(--z));
  transform-origin: 0 0;
}

.checked {
  background-image: linear-gradient(to right, rgba(192, 192, 192, 0.75), rgba(192, 192, 192, 0.75)),
    linear-gradient(to right, black 50%, white 50%),
    linear-gradient(to bottom, black 50%, white 50%);
  background-blend-mode: normal, difference, normal;
  background-size: 2em 2em;
}

.controls {
  background: rgba(255, 255, 255, .2);
  border: solid rgba(255, 255, 255, .6);
  border-radius: .3em 0 0 .3em;
  border-width: 1px 0 1px 1px;
  padding: .2em .2em .5em;
  position: fixed;
  right: 0;
  top: 1em;
}

.controls button {
  appearance: none;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.controls button.toggle:after {
  content: '\\27f5';
}

.controls.left {
  border-radius: 0 .3em .3em 0;
  border-width: 1px 1px 1px 0;
  left: 0;
  right: auto;
}

.controls.left header {
  text-align: right;
}

.controls.left button.toggle:after {
  content: '\\27f6';
}

.controls .zoom-level {
  font-family: sans-serif;
  text-align: center;
}
`
      .replace(/\s*,\s*/g, ',')
      .replace(/\s*>\s*/g, '>')
      .replace(/\s*;\s*}\s*/g, '}')
      .replace(/\s*{\s*/g, '{')
      .replace(/\s*:\s*/g, ':')
      .replace(/\s*;\s*/g, ';');
  }

  private data(): string {
    return `
<style>${this.css()}</style>
<img src="data:${this.imageMimeType};base64,${btoa(this.imageBuffer)}" class="${
      options.get<boolean>('transparencyCheckerboard', false) ? 'checked' : ''
    }">
<div class="controls">
  <header>
    <button class="toggle" title="Toggle position"></button>
  </header>
  <section>
    <button class="zoom-in" title="Zoom in"><img src="data:image/svg+xml;base64,"></button>
    <button class="zoom-out" title="Zoom out"><img src="data:image/svg+xml;base64,"></button>
    <div class="zoom-level">${this.zoomLevel * 100}%</div>
  </section>
  <section>
    <button class="checked" title="Toggle transparency checkerboard">&#x2580;&#x2584;</button>
  </section>
</div>
<script>${this.js()}</script>
`;
  }

  // TODO: this whole renderer should be a separate package with the contents parsed into a minified file
  private js(): string {
    return `
    const image = document.querySelector('img'),
      controls = document.querySelector('.controls'),
      zoomLevel = controls.querySelector('.zoom-level'),
      storeOption = (name, value) => {
        if (!parent) {
          return;
        }
        
        parent.postMessage({name:"setOption",value:{name,value}}, '${
          location.protocol + '//' + location.host
        }');
      };

    document.addEventListener('click', (event) => {
      const target = event.target,
        currentZoom = getComputedStyle(image).getPropertyValue('--z');

      if (target.matches('.zoom-in,.zoom-in *')) {
        const newZoom = currentZoom * 2;

        image.style.setProperty('--z', newZoom);
        zoomLevel.innerText = (newZoom * 100) + '%';
        
        storeOption('zoomLevel', newZoom);
      }

      if (target.matches('.zoom-out,.zoom-out *')) {
        const newZoom = currentZoom / 2;

        image.style.setProperty('--z', newZoom);
        zoomLevel.innerText = (newZoom * 100) + '%';

        storeOption('zoomLevel', newZoom);
      }

      if (target.matches('.toggle,.toggle *')) {
        controls.classList.toggle('left');
      }

      if (target.matches('button.checked')) {
        image.classList.toggle('checked');

        storeOption('transparencyCheckerboard', image.classList.contains('checked'));
      }
    });
    `;
  }

  public matches(mimeType: string): boolean {
    // Using data from: https://en.wikipedia.org/wiki/Comparison_of_web_browsers#Image_format_support
    //   and: https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types/Common_types
    return [
      'image/apng',
      'image/avif',
      'image/bmp',
      'image/gif',
      'image/jpeg',
      'image/png',
      'image/svg+xml',
      'image/vnd.microsoft.icon',
      'image/webp',
    ].includes(mimeType);
  }

  public reset(): void {
    super.reset();

    this.imageBuffer = '';
  }

  public write(char: number): void;
  public write(data: string): void;
  public write(char: number | string): void {
    if (typeof char === 'number') {
      char = String.fromCharCode(char);
    }

    this.imageBuffer += char;
    this.buffer = '';

    super.write(this.data());
  }
}

export default Image;
